service.method:

			SELECT #DB_OWNER#NVL(MAX(CONVERT(numeric, SIGN_SEQ)),0) + 1 AS SIGN_SEQ
  			 FROM SUDSM
			WHERE HOUSE_CODE 	= ${session.HOUSE_CODE}
   			 AND COMPANY_CODE 	= ${session.COMPANY_CODE}
   			 AND USER_ID 		= ${session.ID}


SELECT #DB_OWNER#NVL(MAX(CONVERT(numeric, SIGN_SEQ)),0) MAX_SEQ
  FROM SUDSM
 WHERE 1=1 
   AND HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND USER_ID      = ${session.ID}


		UPDATE SUDSM
      	   SET DES_FILE_NAME  = ${DES_FILE_NAME}
			 , SRC_FILE_NAME  = ${SRC_FILE_NAME}
			 , SIGN_TYPE      = ${SIGN_TYPE}
			 , ATTACH_NO      = ${SIGN_ATTACH_NO}
			 , CHANGE_DATE 	  = ${current.DATE}
			 , CHANGE_TIME    = ${current.TIME}
			 , CHANGE_USER_ID = ${session.ID}
	     WHERE HOUSE_CODE     = ${session.HOUSE_CODE}
		   AND COMPANY_CODE   = ${session.COMPANY_CODE}
		   AND USER_ID        = ${session.ID}
		   AND SIGN_SEQ       = ${SIGN_SEQ}
		   AND DEL_FLAG       = 'N'


DELETE FROM SUDSM
WHERE HOUSE_CODE = ${HOUSE_CODE}
AND COMPANY_CODE = ${COMPANY_CODE} 
AND USER_ID = ${USER_ID}
AND SIGN_SEQ = ${SIGN_SEQ}
